do
local ok_wh, err_wh = pcall(function()
_G.LD_WH = _G.LD_WH or {}
local wh = _G.LD_WH
if wh.Enabled == nil then wh.Enabled = false end
wh.URL = wh.URL or ""
wh.UserID = wh.UserID or ""
wh.Label = wh.Label or game:GetService("Players").LocalPlayer.Name
wh.Plants = wh.Plants or {}
wh.Rarities = wh.Rarities or {}
wh.HatchRarities = wh.HatchRarities or {}
if wh.PingOnHatch == nil then wh.PingOnHatch = false end
if wh.PingOnTarget == nil then wh.PingOnTarget = false end
wh.Cooldown = wh.Cooldown or 5
local req = http_request or request or (syn and syn.request) or (fluxus and fluxus.request)
local HS = game:GetService("HttpService")
local plr = game:GetService("Players").LocalPlayer
local recent = {}
local function setToList(t) local out = {} for k,v in pairs(t) do if v then table.insert(out, k) end end return out end
local function send(title, desc, color, doPing)
    if not wh.Enabled then return end
    if wh.URL == "" then return end
    if not req then warn("[Lamduck] Webhook: no HTTP support") return end
    local content = ""
    if doPing and wh.UserID ~= "" then content = "<@" .. wh.UserID .. ">" end
    local body = HS:JSONEncode({content = content, embeds = {{title = title, description = desc, color = color or 5814783, footer = {text = "Account: " .. wh.Label .. " (" .. plr.Name .. ")"}}}})
    pcall(function() req({Url = wh.URL, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = body}) end)
end
_G.LD_Webhook_Send = send
local function isTargetName(n)
    if not n then return false end
    if wh.Plants[tostring(n)] then return true end
    local low = tostring(n):lower()
    for k,v in pairs(wh.Plants) do if v and tostring(k):lower() == low then return true end end
    return false
end
local function isTargetRarity(r)
    if not r then return false end
    return wh.Rarities[tostring(r)] == true
end
local function onItem(tool)
    task.wait(0.15)
    if not tool then return end
    if not tool.GetAttribute then return end
    local cat = tool:GetAttribute("InventoryCategory")
    local name = tool:GetAttribute("trueName") or tool:GetAttribute("PlantName") or tool:GetAttribute("PetName") or tool.Name
    if not name then return end
    if name == "" then return end
    local rar = tool:GetAttribute("Rarity") or tool:GetAttribute("RarityName") or tool:GetAttribute("rarity")
    local mut = tool:GetAttribute("PlantMutation") or tool:GetAttribute("Mutation") or tool:GetAttribute("mutation")
    local hit = isTargetName(name) or isTargetRarity(rar)
    local title, desc, color, doPing
    if hit then
        doPing = wh.PingOnTarget
        title = "Цель: " .. tostring(name)
        desc = "Категория: " .. tostring(cat or "?") .. "\nРедкость: " .. tostring(rar or "?")
        if mut then desc = desc .. "\nМутация: " .. tostring(mut) end
        color = 16766720
    elseif cat == "Pets" and wh.HatchRarities[tostring(rar or "")] then
        doPing = wh.PingOnHatch
        title = "Вылупился питомец: " .. tostring(name)
        desc = "Редкость: " .. tostring(rar or "?") .. "\nАккаунт: " .. wh.Label
        local mult = tool:GetAttribute("EarningsMultiplier") or tool:GetAttribute("earningsMultiplier")
        if mult then desc = desc .. "\nМножитель дохода: x" .. tostring(mult) end
        local sz = tool:GetAttribute("PetSize") or tool:GetAttribute("petSize")
        if sz then desc = desc .. "\nРазмер: " .. tostring(sz) end
        color = 3447003
    end
    if title then
        local key = tostring(name) .. tostring(rar or "") .. tostring(mut or "")
        local now = tick()
        if not recent[key] or now - recent[key] >= wh.Cooldown then
            recent[key] = now
            send(title, desc, color, doPing)
        end
    end
end
local function hookBp(bp) if bp then bp.ChildAdded:Connect(onItem) end end
hookBp(plr:FindFirstChild("Backpack") or plr:WaitForChild("Backpack", 10))
plr.CharacterAdded:Connect(function() task.wait(0.5) hookBp(plr:WaitForChild("Backpack", 10)) end)
local tab
local ok_tab = pcall(function() tab = K:Tab({["Title"] = "Discord", ["Icon"] = "bell"}) end)
if not ok_tab or not tab then tab = x["TabConfig"] end
if not tab then warn("[Lamduck] Webhook: no tab available") return end
tab:Section({["Title"] = "DISCORD WEBHOOK"})
tab:Paragraph({["Title"] = "Как настроить", ["Desc"] = "1) Discord канал > Настройки > Интеграции > Вебхуки > Создать > Копировать URL.\n2) Discord > Настройки > Дополнительно > Режим разработчика. ПКМ по своему нику > Копировать ID.\n3) Вставь URL, ID, метку аккаунта. Выбери что отслеживать. Включи галочку. Жми Тест."})
tab:Input({["Title"] = "Webhook URL", ["Desc"] = "Ссылка из настроек канала Discord", ["Value"] = wh.URL, ["Placeholder"] = "https://discord.com/api/webhooks/...", ["Callback"] = function(v) wh.URL = tostring(v or "") end})
tab:Input({["Title"] = "Discord ID", ["Desc"] = "Только цифры. Нужен для пинга.", ["Value"] = wh.UserID, ["Placeholder"] = "123456789012345678", ["Callback"] = function(v) wh.UserID = tostring(v or ""):gsub("%D", "") end})
tab:Input({["Title"] = "Метка аккаунта", ["Desc"] = "Чтобы отличать с какого акка пришло (Главный/Альт)", ["Value"] = wh.Label, ["Placeholder"] = "Главный", ["Callback"] = function(v) wh.Label = tostring(v or "") end})
tab:Toggle({["Title"] = "Включить Webhook", ["Desc"] = "Без галки ничего не отправляется", ["Value"] = wh.Enabled, ["Callback"] = function(v) wh.Enabled = v end})
tab:Section({["Title"] = "ЧТО ОТСЛЕЖИВАТЬ"})
tab:Dropdown({["Title"] = "Целевые растения", ["Desc"] = "Если выпадет в инвентарь — пришлёт сообщение", ["Values"] = _G["CachedIndexSeedEntries"] or {}, ["Value"] = setToList(wh.Plants), ["Multi"] = true, ["Callback"] = function(v) wh.Plants = {} if type(v) == "table" then for _, name in pairs(v) do local clean = string.match(tostring(name), "%] (.*)") or tostring(name) wh.Plants[clean] = true end end end})
tab:Dropdown({["Title"] = "Целевые редкости", ["Desc"] = "Любой предмет такой редкости — уведомление", ["Values"] = {"Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Exclusive", "Secret"}, ["Value"] = setToList(wh.Rarities), ["Multi"] = true, ["Callback"] = function(v) wh.Rarities = {} if type(v) == "table" then for _, r in pairs(v) do wh.Rarities[tostring(r)] = true end end end})
